"""Qualify the actual NetworkJobWire adapter over the composed transport."""
import argparse,hashlib,importlib,json,os,subprocess,sys
from pathlib import Path
from layout_text import LayoutText
HERE=Path(__file__).resolve().parent.parent
def run(cmd,*,cwd=HERE,env=None):
 r=subprocess.run(list(map(str,cmd)),cwd=cwd,capture_output=True,env=env);assert r.returncode==0,(cmd,r.returncode,r.stdout[-2000:],r.stderr[-8000:]);return r.stdout
HOST=r'''
#include "network_job_engine.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define CHECK(x) check((x),__LINE__)
static void check(bool ok,int line){if(!ok){fprintf(stderr,"job engine check failed at %d\n",line);exit(1);}}
static const NetworkEngineMac LOCAL={{0x52,0x54,0,0x12,0x34,0x56}},PEER={{2,0,0,0,0,1}};
static void p16(NetworkEngineFrame *f,size_t n,uint16_t v){f->bytes[n]=(uint8_t)(v>>8);f->bytes[n+1]=(uint8_t)v;}static void p32(NetworkEngineFrame *f,size_t n,uint32_t v){f->bytes[n]=(uint8_t)(v>>24);f->bytes[n+1]=(uint8_t)(v>>16);f->bytes[n+2]=(uint8_t)(v>>8);f->bytes[n+3]=(uint8_t)v;}
static NetworkEngineFrame arp(uint32_t sender,uint32_t target){NetworkEngineFrame f={0};f.length=60;for(size_t i=0;i<6;i++){f.bytes[i]=LOCAL.bytes[i];f.bytes[6+i]=PEER.bytes[i];f.bytes[22+i]=PEER.bytes[i];f.bytes[32+i]=LOCAL.bytes[i];}p16(&f,12,0x0806);p16(&f,14,1);p16(&f,16,0x0800);f.bytes[18]=6;f.bytes[19]=4;p16(&f,20,2);p32(&f,28,sender);p32(&f,38,target);return f;}
static NetworkEnginePayload payload(size_t n,uint8_t salt){NetworkEnginePayload p={0};p.len=n;for(size_t i=0;i<n;i++)p.bytes[i]=(uint8_t)(i*11+salt);return p;}
static NetworkTcpPacket take_tcp(NetworkEngineTransport *e){NetworkEngineFrameResult r=network_engine_transport_take_frame(e);CHECK(r.present);NetworkTcpPacket t=network_engine_tcp_decode(&r.frame);CHECK(t.valid);return t;}
static NetworkTcpPacket connect(NetworkEngineTransport *e,uint64_t now){network_engine_transport_advance(e,now);NetworkEngineFrameResult q=network_engine_transport_take_frame(e);CHECK(q.present&&network_engine_arp_decode(&q.frame).valid);NetworkEngineFrame reply=arp(e->base.config.http,e->base.config.local);CHECK(network_engine_transport_submit(e,&reply)==0);network_engine_transport_advance(e,now+1);NetworkTcpPacket syn=take_tcp(e);NetworkEnginePayload empty={0};NetworkEngineFrame synack={0};CHECK(network_engine_tcp_build(&synack,e->base.mac,PEER,e->client.remote_ip,e->client.local_ip,e->client.remote_port,e->client.local_port,900,syn.sequence+1,NETWORK_TCP_SYN|NETWORK_TCP_ACK,8192,&empty));CHECK(network_engine_transport_submit(e,&synack)==0);network_engine_transport_advance(e,now+2);CHECK(take_tcp(e).flags==NETWORK_TCP_ACK);return syn;}
static void ack(NetworkEngineTransport *e,uint64_t now){NetworkEnginePayload empty={0};NetworkEngineFrame f={0};CHECK(network_engine_tcp_build(&f,e->base.mac,PEER,e->client.remote_ip,e->client.local_ip,e->client.remote_port,e->client.local_port,e->client.rcv_nxt,e->client.pending_end,NETWORK_TCP_ACK,8192,&empty));CHECK(network_engine_transport_submit(e,&f)==0);network_engine_transport_advance(e,now);}
static void policies(void){for(unsigned s=NETWORK_TCP_CLOSED;s<=NETWORK_TCP_FAILED;s++){bool peer_fin=s>=NETWORK_TCP_CLOSE_WAIT&&s<=NETWORK_TCP_TIME_WAIT;NetworkJobLink l=network_job_engine_link_policy(false,false,(NetworkTcpClientState)s,peer_fin);if(s==NETWORK_TCP_SYN_SENT)CHECK(l==NETWORK_JOB_LINK_OPENING);else if(s>=NETWORK_TCP_ESTABLISHED&&s<=NETWORK_TCP_FIN_WAIT2)CHECK(l==NETWORK_JOB_LINK_OPEN);else if(peer_fin)CHECK(l==NETWORK_JOB_LINK_PEER_FIN);else CHECK(l==NETWORK_JOB_LINK_CLOSED);}CHECK(network_job_engine_link_policy(true,false,NETWORK_TCP_CLOSED,false)==NETWORK_JOB_LINK_OPENING);CHECK(network_job_engine_link_policy(false,false,NETWORK_TCP_CLOSED,true)==NETWORK_JOB_LINK_PEER_FIN);CHECK(network_job_engine_link_policy(false,true,NETWORK_TCP_CLOSED,true)==NETWORK_JOB_LINK_CLOSED);CHECK(network_job_engine_link_policy(false,true,NETWORK_TCP_ESTABLISHED,false)==NETWORK_JOB_LINK_CLOSED);CHECK(network_job_engine_error_policy(NETWORK_ENGINE_STOPPED)==NETWORK_JOB_OFFLINE);CHECK(network_job_engine_error_policy(NETWORK_ENGINE_BUSY)==NETWORK_JOB_IO);}
static void callbacks(void){NetworkEngineTransport e;NetConfig c=net_config_controlled();CHECK(network_engine_transport_init(&e,c,LOCAL,0)==0);NetworkJobEngineContext context={&e,false};NetworkJobWire wire=network_job_engine_wire(&context);NetworkJobWireResult begin=network_job_wire_begin(wire,1);CHECK(begin.ok&&wire.link(wire.context)==NETWORK_JOB_LINK_OPENING);connect(&e,1);CHECK(wire.link(wire.context)==NETWORK_JOB_LINK_OPEN);
 uint8_t bytes[200];for(size_t i=0;i<sizeof(bytes);i++)bytes[i]=(uint8_t)(i*7);NetworkJobReadView input={bytes,sizeof(bytes)};NetworkJobWireResult sent=network_job_wire_send(wire,input,0,sizeof(bytes));CHECK(sent.ok&&sent.count==sizeof(bytes)&&wire.queued(wire.context)==sizeof(bytes));network_engine_transport_advance(&e,4);CHECK(take_tcp(&e).payload_length==sizeof(bytes));ack(&e,5);CHECK(wire.queued(wire.context)==0);
 NetworkEnginePayload incoming=payload(123,9);NetworkEngineFrame peerdata={0};CHECK(network_engine_tcp_build(&peerdata,e.base.mac,PEER,e.client.remote_ip,e.client.local_ip,e.client.remote_port,e.client.local_port,e.client.rcv_nxt,e.client.snd_nxt,NETWORK_TCP_PSH|NETWORK_TCP_ACK,8192,&incoming));CHECK(network_engine_transport_submit(&e,&peerdata)==0);network_engine_transport_advance(&e,6);(void)network_engine_transport_take_frame(&e);uint8_t out[128]={0};NetworkJobWriteView view={out,sizeof(out)};NetworkJobWireResult received=network_job_wire_receive(wire,view,0,128);CHECK(received.ok&&received.count==123&&!memcmp(out,incoming.bytes,123));
 wire.finish_send(wire.context);network_engine_transport_advance(&e,7);CHECK((take_tcp(&e).flags&NETWORK_TCP_FIN)!=0);ack(&e,8);CHECK(wire.link(wire.context)==NETWORK_JOB_LINK_OPEN);NetworkEnginePayload empty={0};NetworkEngineFrame fin={0};CHECK(network_engine_tcp_build(&fin,e.base.mac,PEER,e.client.remote_ip,e.client.local_ip,e.client.remote_port,e.client.local_port,e.client.rcv_nxt,e.client.snd_nxt,NETWORK_TCP_FIN|NETWORK_TCP_ACK,8192,&empty));CHECK(network_engine_transport_submit(&e,&fin)==0);network_engine_transport_advance(&e,9);CHECK(wire.link(wire.context)==NETWORK_JOB_LINK_PEER_FIN);wire.abort(wire.context);CHECK(wire.link(wire.context)==NETWORK_JOB_LINK_CLOSED);
 network_engine_transport_stop(&e,NETWORK_ENGINE_STOPPED);begin=network_job_wire_begin(wire,2);CHECK(!begin.ok&&begin.error==NETWORK_JOB_OFFLINE);}
static void tls_selection(void){NetworkEngineTransport e;NetConfig c=net_config_controlled();CHECK(network_engine_transport_init(&e,c,LOCAL,0)==0);NetworkJobEngineContext context={&e,true};NetworkJobWire wire=network_job_engine_wire(&context);CHECK(network_job_wire_begin(wire,5).ok);NetworkTcpPacket syn=connect(&e,1);CHECK(syn.destination_port==NET_CONFIG_TLS_PORT);}
static uint32_t job_call(NetworkJobMachine *m,NetworkJobWire wire,NetworkJobIdentity owner,NetworkJobRequest r,uint64_t now,const NetworkJobResolution *resolution){CHECK(network_job_machine_handle_resolved(m,owner,r,now,false,resolution,0,wire));NetworkJobPendingReply p=network_job_machine_pending_reply(m);CHECK(p.present);NetworkJobReplyDecode d=network_job_decode_reply(p.word,r.seq);CHECK(d.valid);network_job_machine_reply_accepted(m);CHECK(d.success);return d.value;}
static void jobs_begin_uses_real_adapter(void){NetworkEngineTransport e;NetConfig c=net_config_controlled();CHECK(network_engine_transport_init(&e,c,LOCAL,0)==0);NetworkJobEngineContext context={&e,false};NetworkJobWire wire=network_job_engine_wire(&context);NetworkJobMachine jobs;network_job_machine_init(&jobs);NetworkJobIdentity owner={7,70};NetworkJobResolution resolution={owner,1,{10,0,2,2},0,100};NetworkJobRequest begin={1,NETWORK_JOB_BEGIN_RESOLVED,0,1,0,1};uint32_t ticket=job_call(&jobs,wire,owner,begin,0,&resolution);CHECK(ticket==1);NetworkJobRequest write={2,NETWORK_JOB_WRITE,0,1,ticket,'X'};CHECK(job_call(&jobs,wire,owner,write,0,&resolution)==1);NetworkJobRequest start={3,NETWORK_JOB_START,0,0,ticket,0};CHECK(job_call(&jobs,wire,owner,start,0,&resolution)==0);CHECK(e.client_pending&&e.client_ticket==ticket);NetworkJobRequest duplicate=start;CHECK(job_call(&jobs,wire,owner,duplicate,0,&resolution)==0);CHECK(e.client_pending&&e.client_ticket==ticket);}
int main(void){policies();callbacks();tls_selection();jobs_begin_uses_real_adapter();puts("PASS actual jobs wire adapter policy callbacks and start integration");return 0;}
'''
def main():
 p=argparse.ArgumentParser();p.add_argument('--cesta',type=Path,required=True);p.add_argument('--cesta-source',type=Path);p.add_argument('--lean-root',type=Path);p.add_argument('--output',type=Path,default=HERE/'build/network-job-engine-tests');a=p.parse_args();w=a.output.resolve();w.mkdir(parents=True,exist_ok=True);inv=json.loads((HERE/'interfaces/network_job_engine.source.json').read_text())
 for path,key in ((inv['jobs_path'],'jobs_sha256'),(inv['main_path'],'main_sha256')):actual=run(['git','show',f"{inv['pin']}:{path}"],cwd=HERE.parent);assert hashlib.sha256(actual).hexdigest()==inv[key]
 host=w/'host.c';host.write_text(HOST);names=('network_job_abi','network_job_wire','network_job_machine','network_config','network_engine_frame','network_engine_packet','network_engine_tcp_packet','network_tcp_client','network_tcp_listener','network_engine_neighbor','network_dns_codec','network_engine_dns','network_engine_transport','network_job_engine_policy','network_job_engine_adapter');exports={};plans={};configs=[]
 for cc in ('gcc','clang'):
  sources=[]
  for name in names:
   out=w/f'{name}-{cc}.c';cmd=[a.cesta,'export-c',f'src/{name}.cesta','--cc',cc,'--std=c11','-o',out]
   if name=='network_job_engine_policy':plan=w/f'{name}-{cc}.plan';cmd.extend(['--plan',plan]);exports['policy-'+cc]=out;plans[cc]=plan
   if name=='network_job_engine_adapter':exports['adapter-'+cc]=out
   run(cmd+['--','-Igenerated/include']);sources.append(out)
  for mode,flags in (('O0',['-O0']),('O2',['-O2']),('SAN',['-O1','-fsanitize=address,undefined','-fno-sanitize-recover=all','-fno-pie','-no-pie'])):
   b=w/f'{cc}-{mode}';run([cc,'-std=c11','-Wall','-Wextra','-Wpedantic','-Werror',*flags,'-Igenerated/include',*sources,host,'-o',b]);actual=run([b],env={**os.environ,'ASAN_OPTIONS':'detect_leaks=1:abort_on_error=1'});configs.append({'compiler':cc,'mode':mode,'sha256':hashlib.sha256(actual).hexdigest()})
 policy=LayoutText(exports['policy-gcc'].read_text());adapter=LayoutText(exports['adapter-gcc'].read_text());mutations=[('stopped-link','if(stopped)return NETWORK_JOB_LINK_CLOSED','if(false)return NETWORK_JOB_LINK_CLOSED','policy'),('opening-link','pending||state==NETWORK_TCP_SYN_SENT','false','policy'),('peer-fin-link','state==NETWORK_TCP_CLOSE_WAIT','false','policy'),('closed-peer-fin','peer_fin&&(state==NETWORK_TCP_CLOSED','false&&(state==NETWORK_TCP_CLOSED','policy'),('offline-error','error==NETWORK_ENGINE_STOPPED','false','policy'),('tls-selection','context->tls','false','adapter'),('receive-capacity','capacity>NETWORK_TCP_TURN_BYTES','capacity>=128','adapter'),('send-capacity','length>NETWORK_TCP_TURN_BYTES','length>=200','adapter'),('finish-callback','network_engine_transport_client_finish(context->engine)','(void)context','adapter'),('abort-callback','network_engine_transport_client_abort(context->engine)','(void)context','adapter')];caught=[];prefix=[w/f'{n}-gcc.c' for n in names if n not in ('network_job_engine_policy','network_job_engine_adapter')]
 for name,old,new,which in mutations:
  text=policy if which=='policy' else adapter;assert text.count(old)>=1,(name,text.count(old));mutp=w/f'mutant-{name}-policy.c';muta=w/f'mutant-{name}-adapter.c';mutp.write_text(text.replace(old,new) if which=='policy' else policy);muta.write_text(text.replace(old,new) if which=='adapter' else adapter);b=w/f'mutant-{name}';run(['gcc','-std=c11','-O2','-Igenerated/include',*prefix,mutp,muta,host,'-o',b]);r=subprocess.run([b],cwd=HERE,capture_output=True);assert r.returncode!=0,('survived',name,r.stdout,r.stderr);caught.append(name)
 admission=[]
 if a.lean_root:
  assert a.cesta_source;sys.path.insert(0,str(a.cesta_source.resolve()/'tests'));h=importlib.import_module('ownership_admission');unique={}
  for plan in plans.values():unique[hashlib.sha256(plan.read_bytes()).hexdigest()]=plan
  for i,plan in enumerate(unique.values()):(record,)=h.parse(plan.read_bytes());admission.append(h.admit_record(record,w/f'JobEngine{i}.lean',a.lean_root.resolve()))
 (w/'summary.json').write_text(json.dumps({'pin':inv['pin'],'configurations':configs,'mutants_caught':caught,'admission':admission,'native_adapter':'tested boundary; callback behavior is not part of the Lean plan'},indent=2)+'\n');print('network job engine:',len(configs),'configurations;',len(caught),'mutants;',sum(x['functions'] for x in admission),'policy plans admitted')
if __name__=='__main__':main()
